-- Fase 84: Network Operations Center. Read/correlation plane over official domains.
-- It does not replace Incidents 59, Notifications 52, Observability 26 or domain state.
-- quality: allow-nonconcurrent-index reason=new-empty-network-operations-tables
alter table public.plans add column if not exists network_operations_center_enabled boolean not null default false;
alter table public.plans add column if not exists noc_network_view_enabled boolean not null default false;
alter table public.plans add column if not exists noc_predictive_risk_enabled boolean not null default false;
alter table public.plans add column if not exists noc_cross_domain_correlation_enabled boolean not null default false;

create table public.network_operations_member_permissions(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{noc:view}',region_ids uuid[] not null default '{}',store_ids uuid[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(organization_id,user_id),check(permissions <@ array['noc:view','noc:view_store','noc:view_region','noc:view_network','noc:view_financial_impact','noc:acknowledge_alert','noc:suppress_alert','noc:create_incident_candidate','noc:execute_response_action','noc:view_sensitive_operational','noc:manage_rules','noc:manage_settings']::text[]));
create or replace function private.noc_allowed(target_organization uuid,requested_permission text default 'noc:view') returns boolean language sql stable security definer set search_path='' as $$select private.is_superadmin() or (target_organization is not null and (exists(select 1 from public.network_operations_member_permissions p where p.organization_id=target_organization and p.user_id=(select auth.uid()) and p.active and requested_permission=any(p.permissions)) or exists(select 1 from public.organization_members m where m.organization_id=target_organization and m.user_id=(select auth.uid()) and m.active and m.role in('owner','admin'))))$$;
revoke all on function private.noc_allowed(uuid,text) from public,anon,authenticated;grant execute on function private.noc_allowed(uuid,text) to authenticated,service_role;

create table public.network_operation_signals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,region_id uuid,source_domain text not null check(source_domain in('orders','kds','inventory','wms','tms','delivery','hardware','integrations','payments','fiscal','offline','assets','quality','capacity','workforce')),source_type text not null,source_id text not null,signal_type text not null check(signal_type in('availability','latency','backlog','capacity','stock','hardware','integration','network','payment','fiscal','quality','transport','workforce','incident','offline','operational_exception')),severity text not null check(severity in('info','warning','high','critical')),status text not null default 'active' check(status in('active','acknowledged','resolved','suppressed','stale')),occurred_at timestamptz not null,detected_at timestamptz not null default now(),resolved_at timestamptz,freshness_at timestamptz not null,correlation_key text,metadata_ref jsonb not null default '{}',created_at timestamptz not null default now(),check(jsonb_typeof(metadata_ref)='object'),unique(organization_id,source_domain,source_type,source_id,signal_type,detected_at));
create table public.store_operational_health(organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid primary key references public.establishments(id) on delete cascade,region_id uuid,overall_status text not null check(overall_status in('healthy','attention','degraded','critical','offline','unknown')),orders_status text not null default 'unknown',kitchen_status text not null default 'unknown',inventory_status text not null default 'unknown',integration_status text not null default 'unknown',hardware_status text not null default 'unknown',payment_status text not null default 'unknown',delivery_status text not null default 'unknown',connectivity_status text not null default 'unknown',active_incident_count integer not null default 0 check(active_incident_count>=0),orders_at_risk integer not null default 0 check(orders_at_risk>=0),reason_codes text[] not null default '{}',source_freshness jsonb not null default '{}',expected_open boolean not null default true,maintenance_active boolean not null default false,last_updated_at timestamptz not null,stale_after timestamptz not null,check(stale_after>=last_updated_at));
create table public.network_health_rollups(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scope_type text not null check(scope_type in('organization','brand','region')),scope_id text not null,expected_store_count integer not null default 0,healthy_count integer not null default 0,attention_count integer not null default 0,degraded_count integer not null default 0,critical_count integer not null default 0,offline_count integer not null default 0,unknown_count integer not null default 0,orders_at_risk integer not null default 0,data_as_of timestamptz not null,stale_after timestamptz not null,created_at timestamptz not null default now(),unique(organization_id,scope_type,scope_id,data_as_of));
create table public.network_correlated_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,title text not null,event_type text not null check(event_type in('local_store_issue','regional_issue','shared_service_issue','provider_issue','integration_issue','capacity_issue','supply_issue','network_outage','multi_domain_issue')),severity text not null check(severity in('info','warning','high','critical')),scope_type text not null check(scope_type in('store','region','network','provider','shared_service')),scope_refs jsonb not null default '[]',primary_signal_id uuid references public.network_operation_signals(id) on delete set null,signal_count integer not null default 1 check(signal_count>0),probable_common_factor text,confidence text not null check(confidence in('high','medium','low')),root_cause_status text not null default 'possible' check(root_cause_status in('possible','suspected','confirmed')),status text not null default 'active' check(status in('active','investigating','monitoring','resolved','suppressed')),incident_id uuid references public.operational_incidents(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(root_cause_status<>'confirmed' or incident_id is not null));
create table public.network_correlated_event_signals(organization_id uuid not null references public.organizations(id) on delete cascade,event_id uuid not null references public.network_correlated_events(id) on delete cascade,signal_id uuid not null references public.network_operation_signals(id) on delete cascade,created_at timestamptz not null default now(),primary key(event_id,signal_id));
create table public.network_alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,correlated_event_id uuid not null references public.network_correlated_events(id) on delete cascade,alert_type text not null,severity text not null check(severity in('info','warning','high','critical')),priority text not null check(priority in('P1','P2','P3','P4')),priority_explanation jsonb not null default '[]',status text not null default 'new' check(status in('new','acknowledged','investigating','monitoring','resolved','suppressed')),created_at timestamptz not null default now(),acknowledged_at timestamptz,acknowledged_by uuid references auth.users(id),suppression_reason text check(suppression_reason is null or suppression_reason in('known_maintenance','duplicate','accepted_risk','test','false_positive')),suppression_expires_at timestamptz,resolved_at timestamptz,unique(correlated_event_id,alert_type));
create table public.network_operational_impacts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,correlated_event_id uuid not null references public.network_correlated_events(id) on delete cascade,store_count integer not null default 0,order_count integer not null default 0,order_backlog integer not null default 0,capacity_loss numeric,stockout_count integer not null default 0,delivery_delay_minutes numeric,revenue_at_risk_cents bigint,estimate_quality text not null default 'unknown' check(estimate_quality in('complete','partial','managerial_estimate','unknown')),actual_loss boolean not null default false,data_as_of timestamptz not null,created_at timestamptz not null default now(),check(actual_loss=false));
create table public.network_operational_risks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,scope jsonb not null default '{}',risk_type text not null check(risk_type in('stockout','capacity','integration','transport','workforce','supply')),horizon interval not null,severity text not null check(severity in('info','warning','high','critical')),confidence text not null check(confidence in('high','medium','low')),source_model text not null,source_version text,status text not null default 'projected' check(status in('projected','accepted','dismissed','expired','materialized')),digital_twin_scenario_id uuid references public.digital_twin_scenarios(id) on delete set null,valid_until timestamptz,data_as_of timestamptz not null,created_at timestamptz not null default now());
create table public.noc_response_action_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,correlated_event_id uuid references public.network_correlated_events(id) on delete set null,incident_id uuid references public.operational_incidents(id) on delete set null,action_type text not null,target_domain text not null,risk_level text not null check(risk_level in('low','medium','high','critical')),preview jsonb not null default '{}',status text not null default 'requested' check(status in('draft','approval_required','requested','approved','rejected','handed_off','completed','failed','cancelled')),approval_id uuid references public.internal_approvals(id) on delete set null,action_engine_ref text,requested_by uuid not null references auth.users(id),human_confirmed boolean not null default false,automatic_execution boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(automatic_execution=false),check(risk_level not in('high','critical') or (human_confirmed and approval_id is not null)));
create table public.network_recovery_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,correlated_event_id uuid not null references public.network_correlated_events(id) on delete cascade,affected_store_count integer not null,recovered_store_count integer not null,active_signal_count integer not null,data_as_of timestamptz not null,created_at timestamptz not null default now(),check(recovered_store_count between 0 and affected_store_count));
create table public.network_operations_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null check(event_type in('alert_acknowledged','alert_suppressed','incident_candidate_created','response_action_requested','health_rule_changed','correlation_changed','risk_disposition_changed')),entity_type text not null,entity_id uuid,reason text,before_state_redacted jsonb,after_state_redacted jsonb,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());
create table public.network_operations_settings(organization_id uuid primary key references public.organizations(id) on delete cascade,timezone text not null default 'America/Sao_Paulo',realtime_enabled boolean not null default true,cross_domain_correlation_enabled boolean not null default false,predictive_risk_enabled boolean not null default false,default_stale_after_seconds integer not null default 600 check(default_stale_after_seconds between 30 and 86400),raw_signal_retention_days integer not null default 30 check(raw_signal_retention_days between 1 and 365),correlation_cooldown_seconds integer not null default 120 check(correlation_cooldown_seconds between 0 and 3600),created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create index network_signals_active_idx on public.network_operation_signals(organization_id,status,severity,detected_at desc);create index network_signals_store_freshness_idx on public.network_operation_signals(organization_id,store_id,freshness_at desc);create index network_signals_correlation_idx on public.network_operation_signals(organization_id,correlation_key,status) where correlation_key is not null;create index store_health_org_status_idx on public.store_operational_health(organization_id,overall_status,last_updated_at desc);create index network_events_active_idx on public.network_correlated_events(organization_id,status,severity,updated_at desc);create index network_alerts_active_idx on public.network_alerts(organization_id,status,priority,created_at desc);create index network_risks_active_idx on public.network_operational_risks(organization_id,status,severity,data_as_of desc);create index network_audit_org_idx on public.network_operations_audit_events(organization_id,created_at desc);
do $$ declare t text; begin foreach t in array array['network_operations_member_permissions','network_operation_signals','store_operational_health','network_health_rollups','network_correlated_events','network_correlated_event_signals','network_alerts','network_operational_impacts','network_operational_risks','noc_response_action_requests','network_recovery_snapshots','network_operations_audit_events','network_operations_settings'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',left('noc_service_'||t,63),t);end loop;end $$;
revoke all on sequence public.network_operations_audit_events_id_seq from public,anon,authenticated;grant usage,select on sequence public.network_operations_audit_events_id_seq to service_role;
create or replace view public.network_operations_overview with (security_invoker=true) as select h.organization_id,count(*) filter(where h.expected_open and h.overall_status='healthy' and now()<=h.stale_after) healthy_stores,count(*) filter(where h.expected_open and h.overall_status='critical' and now()<=h.stale_after) critical_stores,count(*) filter(where h.expected_open and h.overall_status='offline' and now()<=h.stale_after) offline_stores,count(*) filter(where h.expected_open and (h.overall_status='unknown' or now()>h.stale_after)) unknown_stores,coalesce(sum(h.orders_at_risk) filter(where now()<=h.stale_after),0) orders_at_risk,max(h.last_updated_at) data_as_of from public.store_operational_health h group by h.organization_id;
revoke all on public.network_operations_overview from public,anon,authenticated;grant select on public.network_operations_overview to service_role;
comment on table public.network_operation_signals is 'Normalized references to official domain health; no secrets or raw webhook payloads.';comment on table public.store_operational_health is 'Explainable read model: stale rows render unknown, never healthy.';comment on table public.network_correlated_events is 'Correlation never confirms root cause without an Incident Management link.';comment on table public.noc_response_action_requests is 'Official domain services and ActionEngine remain the only executors.';
